import React, { useRef } from 'react'
import { useFrame } from 'react-three-fiber'
import lerp from 'lerp'

/**
 * Orbit Inspect = presszero.in/mascot behaviour:
 *   orbit.rotation.x = pitch, orbit.rotation.y = yaw
 *   lerp 0.18 while on, ease rotation to 0 at 0.12 while off
 * Move = separate outer group, flat XY only.
 */
export default function MascotInspect({ inspectRef, children }) {
  const panRef = useRef()
  const orbitRef = useRef()
  const smooth = useRef({ rotX: 0, rotY: 0, posX: 0, posY: 0 })

  useFrame(() => {
    if (!panRef.current || !orbitRef.current || !inspectRef?.current) return
    const t = inspectRef.current
    const targetX = t.posX ?? 0
    const targetY = t.posY ?? 0

    // Rotation — identical to presszero (lerp always; snap only on Reset)
    if (t.snap) {
      smooth.current.rotX = t.enabled ? t.rotX : 0
      smooth.current.rotY = t.enabled ? t.rotY : 0
    } else if (!t.enabled) {
      smooth.current.rotX = lerp(smooth.current.rotX, 0, 0.12)
      smooth.current.rotY = lerp(smooth.current.rotY, 0, 0.12)
    } else {
      smooth.current.rotX = lerp(smooth.current.rotX, t.rotX, 0.18)
      smooth.current.rotY = lerp(smooth.current.rotY, t.rotY, 0.18)
    }

    // Pan — planar; snap while actively dragging Move
    if (t.snap || (t.dragging && t.dragMode === 'pan')) {
      smooth.current.posX = targetX
      smooth.current.posY = targetY
    } else if (!t.enabled) {
      // Keep last placement (presszero has no pan; don't yank back to 0)
      smooth.current.posX = lerp(smooth.current.posX, targetX, 0.12)
      smooth.current.posY = lerp(smooth.current.posY, targetY, 0.12)
    } else {
      smooth.current.posX = lerp(smooth.current.posX, targetX, 0.22)
      smooth.current.posY = lerp(smooth.current.posY, targetY, 0.22)
    }

    panRef.current.position.set(smooth.current.posX, smooth.current.posY, 0)
    orbitRef.current.rotation.x = smooth.current.rotX
    orbitRef.current.rotation.y = smooth.current.rotY
  })

  return (
    <group ref={panRef}>
      <group ref={orbitRef}>{children}</group>
    </group>
  )
}
