/** 4K landscape export helpers — JPEG / PDF / SVG (SVG embeds raster). */

export const EXPORT_WIDTH = 3840
export const EXPORT_HEIGHT = 2160
export const EXPORT_SUPERSAMPLE = 2
export const EXPORT_JPEG_QUALITY = 0.98

export function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.rel = 'noopener'
  document.body.appendChild(a)
  a.click()
  a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1500)
}

export function stampFilename(ext) {
  const d = new Date()
  const pad = n => String(n).padStart(2, '0')
  return `voice-zero-mascot-${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}.${ext}`
}

/** Crop a source canvas/image into a new canvas (pixel coords). */
export function cropToCanvas(source, crop) {
  const sx = Math.max(0, Math.floor(crop.x))
  const sy = Math.max(0, Math.floor(crop.y))
  const sw = Math.max(1, Math.floor(crop.width))
  const sh = Math.max(1, Math.floor(crop.height))
  const out = document.createElement('canvas')
  out.width = sw
  out.height = sh
  const ctx = out.getContext('2d')
  ctx.drawImage(source, sx, sy, sw, sh, 0, 0, sw, sh)
  return out
}

export function canvasToJpegBlob(canvas, quality = 0.92) {
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      blob => (blob ? resolve(blob) : reject(new Error('JPEG encode failed'))),
      'image/jpeg',
      quality
    )
  })
}

export async function canvasToJpegDataUrl(canvas, quality = 0.92) {
  const blob = await canvasToJpegBlob(canvas, quality)
  return blobToDataUrl(blob)
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = () => reject(reader.error || new Error('read failed'))
    reader.readAsDataURL(blob)
  })
}

function blobToArrayBuffer(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = () => reject(reader.error || new Error('read failed'))
    reader.readAsArrayBuffer(blob)
  })
}

/** Minimal single-page PDF with an embedded JPEG (no external deps). */
export async function jpegBlobToPdfBlob(jpegBlob, widthPx, heightPx) {
  const jpeg = new Uint8Array(await blobToArrayBuffer(jpegBlob))
  // Page size matches pixel aspect; JPEG keeps full resolution inside the PDF.
  const pageW = widthPx
  const pageH = heightPx

  const objects = []

  const addObj = content => {
    objects.push(content)
    return objects.length
  }

  const catalogId = addObj(null)
  const pagesId = addObj(null)
  const pageId = addObj(null)
  const contentId = addObj(null)
  const imageId = addObj(null)

  objects[catalogId - 1] = `<< /Type /Catalog /Pages ${pagesId} 0 R >>`
  objects[pagesId - 1] = `<< /Type /Pages /Kids [${pageId} 0 R] /Count 1 >>`
  objects[pageId - 1] =
    `<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${pageW} ${pageH}] ` +
    `/Contents ${contentId} 0 R /Resources << /XObject << /Im0 ${imageId} 0 R >> >> >>`
  objects[contentId - 1] = streamObj(`q\n${pageW} 0 0 ${pageH} 0 0 cm\n/Im0 Do\nQ\n`)
  objects[imageId - 1] = jpegImageObj(jpeg, widthPx, heightPx)

  return new Blob([new PdfEncoder().build(objects)], { type: 'application/pdf' })
}

function streamObj(text) {
  const body = encoderUtf8(text)
  return {
    dict: `<< /Length ${body.length} >>`,
    stream: body
  }
}

function jpegImageObj(jpegBytes, w, h) {
  return {
    dict:
      `<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} ` +
      `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpegBytes.length} >>`,
    stream: jpegBytes
  }
}

function encoderUtf8(str) {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(str)
  const out = new Uint8Array(str.length)
  for (let i = 0; i < str.length; i++) out[i] = str.charCodeAt(i) & 0xff
  return out
}

class PdfEncoder {
  build(objects) {
    const chunks = []
    const pushStr = s => chunks.push(encoderUtf8(s))
    const pushBytes = b => chunks.push(b instanceof Uint8Array ? b : new Uint8Array(b))

    pushStr('%PDF-1.4\n')
    const offsets = [0]

    for (let i = 0; i < objects.length; i++) {
      offsets.push(byteLength(chunks))
      const obj = objects[i]
      pushStr(`${i + 1} 0 obj\n`)
      if (obj && typeof obj === 'object' && obj.stream) {
        pushStr(`${obj.dict}\nstream\n`)
        pushBytes(obj.stream)
        pushStr(`\nendstream\nendobj\n`)
      } else {
        pushStr(`${obj}\nendobj\n`)
      }
    }

    const xrefPos = byteLength(chunks)
    pushStr(`xref\n0 ${objects.length + 1}\n`)
    pushStr('0000000000 65535 f \n')
    for (let i = 1; i < offsets.length; i++) {
      pushStr(`${String(offsets[i]).padStart(10, '0')} 00000 n \n`)
    }
    pushStr(
      `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`
    )

    return concatChunks(chunks)
  }
}

function byteLength(chunks) {
  return chunks.reduce((n, c) => n + c.length, 0)
}

function concatChunks(chunks) {
  const total = byteLength(chunks)
  const out = new Uint8Array(total)
  let o = 0
  for (let i = 0; i < chunks.length; i++) {
    out.set(chunks[i], o)
    o += chunks[i].length
  }
  return out
}

/** SVG wrapper around a JPEG data URL — vector container, raster artwork. */
export function jpegDataUrlToSvgBlob(dataUrl, width, height) {
  const svg =
    `<?xml version="1.0" encoding="UTF-8"?>\n` +
    `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" ` +
    `width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">\n` +
    `  <title>Voice Zero Mascot</title>\n` +
    `  <image width="${width}" height="${height}" href="${dataUrl}" xlink:href="${dataUrl}"/>\n` +
    `</svg>\n`
  return new Blob([svg], { type: 'image/svg+xml;charset=utf-8' })
}
