import * as THREE from 'three'
import { useMemo, useRef } from 'react'
import { useFrame } from 'react-three-fiber'

function fillStudioGrey(ctx, size) {
  const grad = ctx.createLinearGradient(0, 0, 0, size)
  grad.addColorStop(0, '#a8adb4')
  grad.addColorStop(0.45, '#8a9098')
  grad.addColorStop(1, '#5a5e66')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, size, size)
}

function drawEnvFace(ctx, size, faceIndex, poolColor, poolSpread, poolStrength) {
  const isTop = faceIndex === 2
  const isBottom = faceIndex === 3

  const poolHex = `#${poolColor.getHexString()}`
  const warm = poolColor.clone()
  warm.lerp(new THREE.Color('#ffffff'), 0.35)
  const warmHex = `#${warm.getHexString()}`
  const spread = Math.max(0.02, Math.min(1, poolSpread))
  const strength = Math.max(0, Math.min(1.5, poolStrength))
  const poolR = Math.round(poolColor.r * 255)
  const poolG = Math.round(poolColor.g * 255)
  const poolB = Math.round(poolColor.b * 255)

  fillStudioGrey(ctx, size)

  if (strength < 0.001) return

  if (isTop) {
    const spotRadius = size * (0.14 + spread * 0.46)
    const radial = ctx.createRadialGradient(size * 0.5, size * 0.1, 0, size * 0.5, size * 0.38, spotRadius)
    radial.addColorStop(0, warmHex)
    radial.addColorStop(0.38, poolHex)
    radial.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = radial
    ctx.fillRect(0, 0, size, size)

    const hlRadius = size * (0.1 + spread * 0.32)
    ctx.save()
    ctx.translate(size * 0.5, size * 0.14)
    ctx.scale(1.0, 0.42 + spread * 0.38)
    ctx.translate(-size * 0.5, -size * 0.14)
    const highlight = ctx.createRadialGradient(size * 0.5, size * 0.14, 0, size * 0.5, size * 0.14, hlRadius)
    highlight.addColorStop(0, `rgba(255, 255, 255, ${0.1 + strength * 0.2})`)
    highlight.addColorStop(0.55, `rgba(255, 255, 255, ${0.03 + strength * 0.06})`)
    highlight.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = highlight
    ctx.fillRect(0, 0, size, size)
    ctx.restore()
    return
  }

  if (isBottom) {
    const floorGrad = ctx.createLinearGradient(0, 0, 0, size)
    floorGrad.addColorStop(0, '#3a3a42')
    floorGrad.addColorStop(1, '#0e1014')
    ctx.fillStyle = floorGrad
    ctx.fillRect(0, 0, size, size)

    const floorGlow = ctx.createRadialGradient(size * 0.5, size * 0.2, 0, size * 0.5, size * 0.55, size * (0.14 + spread * 0.4))
    floorGlow.addColorStop(0, `rgba(${poolR}, ${poolG}, ${poolB}, ${0.1 + strength * 0.32})`)
    floorGlow.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = floorGlow
    ctx.fillRect(0, 0, size, size)
    return
  }

  const sideGrad = ctx.createLinearGradient(0, 0, 0, size)
  sideGrad.addColorStop(0, warmHex)
  sideGrad.addColorStop(0.22 + spread * 0.18, poolHex)
  sideGrad.addColorStop(0.55, '#707680')
  sideGrad.addColorStop(1, '#1a1a20')
  ctx.globalAlpha = 0.55 + strength * 0.35
  ctx.fillStyle = sideGrad
  ctx.fillRect(0, 0, size, size)
  ctx.globalAlpha = 1

  const glowRadius = size * (0.12 + spread * 0.36)
  const glowY = size * (0.12 + spread * 0.28)
  ctx.save()
  ctx.translate(size * 0.5, glowY)
  ctx.scale(0.55 + spread * 0.35, 1.0)
  ctx.translate(-size * 0.5, -glowY)
  const poolGlow = ctx.createRadialGradient(size * 0.5, glowY, 0, size * 0.5, glowY, glowRadius)
  poolGlow.addColorStop(0, `rgba(${poolR}, ${poolG}, ${poolB}, ${0.2 + strength * 0.38})`)
  poolGlow.addColorStop(0.5, `rgba(${poolR}, ${poolG}, ${poolB}, ${0.06 + strength * 0.12})`)
  poolGlow.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = poolGlow
  ctx.fillRect(0, 0, size, size)
  ctx.restore()
}

function createDynamicEnvMap() {
  const size = 1024
  const images = []
  const contexts = []

  for (let i = 0; i < 6; i++) {
    const canvas = document.createElement('canvas')
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext('2d')
    contexts.push(ctx)
    images.push(canvas)
  }

  const cube = new THREE.CubeTexture(images)
  cube.needsUpdate = true
  return { cube, contexts, images, size }
}

export default function SceneEnvironment({ envRef, poolSpreadRef, poolIntensityRef, poolColorRef, visualRef }) {
  const envBundle = useMemo(() => createDynamicEnvMap(), [])
  const poolColor = useRef(new THREE.Color('#f5e6d4'))
  const lastKey = useRef('')

  if (envRef) envRef.current = envBundle.cube

  useFrame(() => {
    const spread = poolSpreadRef?.current ?? 0.52
    const strength = (poolIntensityRef?.current ?? 0.62) * (visualRef?.current?.lightIntensity ?? 1.2)
    if (poolColorRef?.current) poolColor.current.copy(poolColorRef.current)
    else if (visualRef?.current) poolColor.current.set(visualRef.current.light)

    const key = `${spread.toFixed(3)}|${strength.toFixed(3)}|${poolColor.current.getHexString()}`
    if (key === lastKey.current) return
    lastKey.current = key

    for (let i = 0; i < 6; i++) {
      drawEnvFace(envBundle.contexts[i], envBundle.size, i, poolColor.current, spread, strength)
    }
    envBundle.cube.needsUpdate = true
  })

  return null
}
